"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


_MONTHS = {n: i + 1 for i, n in enumerate(
    "JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split())}
_DAYS = {n: i for i, n in enumerate("SUN MON TUE WED THU FRI SAT".split())}


def _value(text: str, names: dict[str, int] | None, high: bool = False) -> int:
    if text.isascii() and text.isdigit():
        return int(text)
    if names is not None and text.upper() in names:
        v = names[text.upper()]
        if high and names is _DAYS and v == 0:
            return 7
        return v
    raise CronError(f"malformed value {text!r}")


def _parse_field(text: str, lo: int, hi: int, names: dict[str, int] | None) -> set[int]:
    result: set[int] = set()
    for term in text.split(","):
        if not term:
            raise CronError(f"empty term in {text!r}")
        base, slash, step_text = term.partition("/")
        step = 1
        if slash:
            if not (step_text.isascii() and step_text.isdigit()):
                raise CronError(f"malformed step in {term!r}")
            step = int(step_text)
            if step < 1:
                raise CronError(f"step must be at least 1 in {term!r}")
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            left, _, right = base.partition("-")
            a = _value(left, names)
            b = _value(right, names, high=True)
            if a > b:
                raise CronError(f"range low above high in {term!r}")
        else:
            a = _value(base, names)
            b = hi if slash else a
        if not (lo <= a <= hi and lo <= b <= hi):
            raise CronError(f"value out of range in {term!r}")
        result.update(range(a, b + 1, step))
    return result


def _add_years(d: datetime, years: int) -> datetime:
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        return d.replace(year=d.year + years, day=28) + timedelta(days=1)


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    fields = expr.split()
    if len(fields) != 5:
        raise CronError("expression must have exactly five fields")
    minutes = sorted(_parse_field(fields[0], 0, 59, None))
    hours = sorted(_parse_field(fields[1], 0, 23, None))
    doms = _parse_field(fields[2], 1, 31, None)
    months = _parse_field(fields[3], 1, 12, _MONTHS)
    dows = {d % 7 for d in _parse_field(fields[4], 0, 7, _DAYS)}
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    if count <= 0:
        return []

    def day_matches(day: datetime) -> bool:
        if day.month not in months:
            return False
        dom_ok = day.day in doms
        dow_ok = (day.weekday() + 1) % 7 in dows
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        if dom_restricted:
            return dom_ok
        if dow_restricted:
            return dow_ok
        return True

    limit = _add_years(start, 5)
    day = start.replace(hour=0, minute=0, second=0, microsecond=0)
    out: list[datetime] = []
    while day <= limit:
        if day_matches(day):
            for h in hours:
                for m in minutes:
                    cand = day.replace(hour=h, minute=m)
                    if cand > start and cand <= limit:
                        out.append(cand)
                        if len(out) == count:
                            return out
        day += timedelta(days=1)
    raise CronError("no firing within five years of start")
